const body = $input.first().json.body || {};

const payload = {
  id_payment: body.id_payment ? String(body.id_payment).trim() : null,
  id_tenant: body.id_tenant ? String(body.id_tenant).trim() : null,
  id_transaction: body.id_transaction ? String(body.id_transaction).trim() : null,
  amount: body.amount !== undefined ? Number(body.amount) : undefined,
  payment_date: body.payment_date ? String(body.payment_date).trim() : undefined,
  payment_method: body.payment_method ? String(body.payment_method).trim() : undefined,
  reference: body.reference ? String(body.reference).trim() : undefined,
  notes: body.notes ? String(body.notes).trim() : undefined,
};

return [{ json: { sqlPayload: payload } }];

const sqlPayload = $input.first().json.sqlPayload;
const errors = [];

if (!sqlPayload.id_payment) errors.push('id_payment es requerido');
if (!sqlPayload.id_tenant) errors.push('id_tenant es requerido');
if (!sqlPayload.id_transaction) errors.push('id_transaction es requerido');
if (sqlPayload.amount !== undefined && (isNaN(sqlPayload.amount) || sqlPayload.amount <= 0)) errors.push('amount debe ser un numero mayor a 0');

if (errors.length > 0) {
  return [{ json: { valid: false, errors } }];
}
return [{ json: { valid: true, sqlPayload } }];

const rows = $input.all();
const row = rows[0];
const sqlPayload = $('Preparar Payload').first().json.sqlPayload;

if (!row || row.json.id_payment === undefined) {
  return [{ json: { exists: false } }];
}

return [{ json: { exists: true, sqlPayload, old_amount: row.json.amount } }];

const sqlPayload = $('Verificar').first().json.sqlPayload;
const oldAmount = $('Verificar').first().json.old_amount || 0;
const newAmount = sqlPayload.amount !== undefined ? Number(sqlPayload.amount) : oldAmount;
const diff = newAmount - oldAmount;

return [{ json: { sqlPayload, diff, newAmount, oldAmount } }];

const payment = $input.first().json;
const diff = $('Calcular Diferencia').first().json.diff;
const sqlPayload = $('Calcular Diferencia').first().json.sqlPayload;

return [{ json: { payment, diff, id_transaction: sqlPayload.id_transaction, id_tenant: sqlPayload.id_tenant } }];
